import assert from 'node:assert/strict';
import test from 'node:test';
import { createCartState, transformTypedPriceModule } from '../src/vite-vue-cart.mjs';

test('Vue reactivity and Vite transformation execute through installed packages', async () => {
  const cart = createCartState([{ productId: 'lamp', quantity: 2 }]);
  assert.equal(cart.itemCount.value, 2);
  cart.addLine({ productId: 'desk', quantity: 1 });
  assert.equal(cart.itemCount.value, 3);
  assert.equal(cart.lines.length, 2);
  const code = await transformTypedPriceModule('export const price: number = 4950');
  assert.doesNotMatch(code, /: number/);
  const transformed = await import(`data:text/javascript;base64,${Buffer.from(code).toString('base64')}`);
  assert.equal(transformed.price, 4950);
});

